		/** 
		 * Tests creating a new DataProvider.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a DataProvider");

			StringBuilder msg = new StringBuilder( "-- Failed to create a DataProvider" );

			try {            
				DataProvider entity = DataProviderService.getDataProviderInstance().createDataProvider( generateNewEntity() );
				thePrimaryKey = entity.getDataProviderId();
				LOGGER.info( "-- Successfully created a DataProvider with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a DataProvider. 
		 */
		public DataProvider testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created DataProvider" );

			DataProvider entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read DataProvider with primary key" );
			msg.append( thePrimaryKey );
			
			DataProviderFetchOneSummary fetchOneSummary = new DataProviderFetchOneSummary( thePrimaryKey );

			try {
				entity = DataProviderService.getDataProviderInstance().getDataProvider( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found DataProvider " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a DataProvider.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a DataProvider." );

			StringBuilder msg = new StringBuilder( "Failed to update a DataProvider : " );        
			DataProvider entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created DataProvider." );

				// for use later on...
				thePrimaryKey = entity.getDataProviderId();

				DataProviderService proxy = DataProviderService.getDataProviderInstance();            
				proxy.updateDataProvider( entity );   

				LOGGER.info( "-- Successfully saved DataProvider - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a DataProvider.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created DataProvider." );

			try{
			    DataProvider entity = testRead(); 
				DataProviderService.getDataProviderInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted DataProvider with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete DataProvider with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all DataProviders.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of DataProviders:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all DataProvider : " );        
			List<DataProvider> collection  = null;

			try {
				// call the static get method on the DataProviderService
				collection = DataProviderService.getDataProviderInstance().getAllDataProvider();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					DataProvider entity = null;            
					Iterator<DataProvider> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getDataProviderId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

